u8 lookupVanillaMapColor(std::string_view stateName)
{
    // 先按原名直查（无属性的方块走这条快路），再按规范化名查。
    for (const auto& [name, color] : MAP_COLOR_TABLE) {
        if (name == stateName) {
            return color;
        }
    }

    const std::string canonical = canonicalStateName(std::string(stateName));
    for (const auto& [name, color] : MAP_COLOR_TABLE) {
        if (name == canonical) {
            return color;
        }
    }
    return 0;
}

std::string canonicalStateName(const std::string& raw)
{
    const std::size_t open = raw.find('[');
    if (open == std::string::npos) {
        return raw;
    }
    const std::size_t close = raw.rfind(']');
    if (close == std::string::npos || close <= open) {
        return raw;
    }

    const std::string head = raw.substr(0, open);
    const std::string body = raw.substr(open + 1, close - open - 1);

    std::vector<std::string> attrs;
    std::string current;
    for (char ch : body) {
        if (ch == ',') {
            if (!current.empty()) {
                attrs.push_back(current);
            }
            current.clear();
        } else {
            current.push_back(ch);
        }
    }
    if (!current.empty()) {
        attrs.push_back(current);
    }
    std::sort(attrs.begin(), attrs.end());

    std::string result = head + "[";
    for (std::size_t i = 0; i < attrs.size(); ++i) {
        if (i > 0) {
            result += ",";
        }
        result += attrs[i];
    }
    result += "]";
    return result;
}

i32 vanillaMapColorTableSize()
{
    return static_cast<i32>(std::size(MAP_COLOR_TABLE));
}

